import ifcopenshell, ifcopenshell.geom
f=ifcopenshell.open('output/model.ifc'); s=ifcopenshell.geom.settings(); s.set('use-world-coords',True)
def b(name):
    p=[e for e in f.by_type('IfcProduct') if e.Name==name][0]
    sh=ifcopenshell.geom.create_shape(s,p); v=sh.geometry.verts
    return tuple(round(x*1000,1) for x in (min(v[0::3]),max(v[0::3]),min(v[1::3]),max(v[1::3]),min(v[2::3]),max(v[2::3])))
for n in ['COL-01','COL-02','Containment Roof Mid 1','Containment Roof Mid 2','Containment Roof Mid 3','Containment Roof South']:
    print(n,b(n))
# overlap check
for c in ['COL-01','COL-02','COL-03','COL-04','COL-05','COL-06']:
    a=b(c)
    for r in ['Containment Roof Mid 1','Containment Roof Mid 2','Containment Roof Mid 3','Containment Roof South']:
        z=b(r)
        ov=[min(a[i+1],z[i+1])-max(a[i],z[i]) for i in (0,2,4)]
        if min(ov)>0: print('overlap',c,r,ov)
EOF

