#!/usr/bin/env python3
"""Independent hard-requirement verification from the submitted IFC only."""
import sys, collections, math
import numpy as np
import ifcopenshell, ifcopenshell.geom, ifcopenshell.util.element as ue

IFC=sys.argv[1] if len(sys.argv)>1 else 'output/model.ifc'
f=ifcopenshell.open(IFC)
s=ifcopenshell.geom.settings(); s.set('use-world-coords',True)
boxes={}
for e in f.by_type('IfcProduct'):
    if not getattr(e,'Representation',None): continue
    try: sh=ifcopenshell.geom.create_shape(s,e)
    except Exception: continue
    v=np.array(sh.geometry.verts,float).reshape(-1,3)*1000.0
    if len(v): boxes[e.id()]=(v.min(0),v.max(0))
def ps(e): return ue.get_psets(e,should_inherit=False)
def pv(e,k):
    for d in ps(e).values():
        if k in d: return d[k]
    return None
def box(e): return boxes[e.id()]
fails=[]
def chk(cond,msg):
    print(('PASS' if cond else 'FAIL'),msg)
    if not cond: fails.append(msg)

# counts
racks=[e for e in f.by_type('IfcFurniture') if e.ObjectType=='Rack']
crahs=[e for e in f.by_type('IfcUnitaryEquipment') if e.ObjectType=='CRAH']
pdus=[e for e in f.by_type('IfcElectricDistributionBoard') if e.ObjectType=='PDU']
cols=f.by_type('IfcColumn')
heads=[e for e in f.by_type('IfcFireSuppressionTerminal') if e.ObjectType=='SprinklerHead']
chk(len(racks)==94,'94 racks (%d)'%len(racks))
chk(len(crahs)==16,'16 CRAHs (%d)'%len(crahs))
chk(len(pdus)==4,'4 PDUs (%d)'%len(pdus))
chk(len(cols)==8,'8 columns (%d)'%len(cols))
chk(len(heads)==104,'104 sprinkler heads (%d)'%len(heads))

# rack rows / tile grid / facing
for r,n in [('A',26),('B',21),('C',20),('D',27)]:
    es=[e for e in racks if pv(e,'Row')==r]
    chk(len(es)==n,'row %s has %d racks (%d)'%(r,n,len(es)))
    bad=[]
    for e in es:
        d=ps(e)['Pset_DCM_Rack']; x0=box(e)[0][0]; y0=box(e)[0][1]
        # box centre minus half width/depth, rotation pi keeps footprint
        w=d['Width_mm']; dep=d['Depth_mm']; cx=(box(e)[0][0]+box(e)[1][0])/2; cy=(box(e)[0][1]+box(e)[1][1])/2
        x0=cx-w/2; y0=cy-dep/2
        if abs(x0/600-round(x0/600))>1e-6 or abs(y0/600-round(y0/600))>1e-6: bad.append(e.Name)
        want='SOUTH' if r in 'AC' else 'NORTH'
        if d['Facing']!=want: bad.append(e.Name+':facing')
    chk(not bad,'row %s tile/facing (%s)'%(r,bad[:3]))

# column height
chk(all(abs(box(e)[0][2])<1e-6 and abs(box(e)[1][2]-3050)<1e-6 for e in cols),'columns 0..3050')

# heads
ceil=[e for e in heads if pv(e,'Kind')=='CEILING']; ais=[e for e in heads if pv(e,'Kind')=='IN_AISLE']
chk(len(ceil)==94 and all(abs(pv(e,'DeflectorZ')-3025)<1e-6 for e in ceil),'94 ceiling heads at +3025')
chk(len(ais)==10 and all(abs(pv(e,'DeflectorZ')-1800)<1e-6 for e in ais),'10 in-aisle heads at +1800')
chk(all(abs(box(e)[1][2]-box(e)[0][2]-3)<1e-6 for e in heads),'heads modelled as thin deflector plates')

# services
svc=collections.defaultdict(list)
for e in f.by_type('IfcProduct'):
    if e.id() in boxes and e.is_a() in ('IfcCableCarrierSegment','IfcCableSegment','IfcPipeSegment'):
        d=pv(e,'Service'); 
        if d: svc[str(d)].append(e)
chk(set(svc)=={'TELECOM','POWER','CHW'},'three service groups present')
for k,es in svc.items():
    zmax=max(box(e)[1][2] for e in es); zmin=min(box(e)[0][2] for e in es)
    chk(zmax<=-55.0,'%s top <= -55 (%.1f)'%(k,zmax))
    chk(zmin>=-600.0,'%s bottom >= -600 (%.1f)'%(k,zmin))
    d=ps(es[0]).get('Pset_DCM_Service',{})
    chk(d.get('UnderFloorLength_mm')==d.get('TotalLength_mm') and d.get('OverheadLength_mm')==0,'%s 100%% under-floor'%k)

# network groups (bbox touch within 5 mm)
groups=collections.defaultdict(list)
for rel in f.by_type('IfcRelAssignsToGroup'):
    g=rel.RelatingGroup
    for o in rel.RelatedObjects or []:
        if o.id() in boxes: groups[g.Name].append(o.id())
def components(ids):
    lo=np.array([boxes[i][0] for i in ids])-5; hi=np.array([boxes[i][1] for i in ids])+5
    par=list(range(len(ids)))
    def root(i):
        while par[i]!=i: par[i]=par[par[i]]; i=par[i]
        return i
    for i in range(len(ids)):
        for j in range(i+1,len(ids)):
            if np.all(lo[i]<=hi[j]) and np.all(lo[j]<=hi[i]): par[root(i)]=root(j)
    return len({root(i) for i in range(len(ids))})
for g,ids in groups.items():
    chk(components(ids)==1,'%s one connected network'%g)

# row coverage / CRAH distance
rows={'A':(1800,21000,3000),'B':(1800,21000,5935),'C':(1800,19800,8400),'D':(1800,21600,11335)}
def segline(e):
    lo,hi=box(e); d=hi-lo; k=int(np.argmax(d)); c=(lo+hi)/2; a=c.copy(); b=c.copy(); a[k]=lo[k]; b[k]=hi[k]
    return a,b
def pdist(p,a,b):
    p=np.array(p[:2]);a=np.array(a[:2]);b=np.array(b[:2]);d=b-a
    if d@d<1e-9:return np.linalg.norm(p-a)
    t=np.clip((p-a)@d/(d@d),0,1);return np.linalg.norm(p-(a+t*d))
for k,es in svc.items():
    for rn,(x0,x1,y) in rows.items():
        ds=[min(pdist((x,y),*segline(e)) for e in es) for x in np.arange(x0,x1+1,100)]
        cov=sum(d<=2500 for d in ds)/len(ds)
        chk(cov>=0.8,'%s row %s coverage %.1f%% >=80'%(k,rn,100*cov))
chw=svc['CHW']
for e in crahs:
    lo,hi=box(e); c=((lo+hi)/2)
    d=min(pdist(c,*segline(q)) for q in chw)
    chk(d<=2500,'CRAH %s CHW distance %.0f <=2500'%(e.Name,d))

# tray-busway separation
def axis_gap(a,b):
    lo1,hi1=boxes[a.id()];lo2,hi2=boxes[b.id()]
    return max(max(lo2[k]-hi1[k],lo1[k]-hi2[k]) for k in range(3))
ming=min(axis_gap(a,b) for a in svc['TELECOM'] for b in svc['POWER'])
chk(ming>=300,'tray-busway min axis clearance %.1f >=300'%ming)

# head clearance and PDU dedicated space
mm=1e9
for h in heads:
    lo,hi=box(h); hx=(lo[0]+hi[0])/2;hy=(lo[1]+hi[1])/2;hz=lo[2]
    for es in svc.values():
        for e in es:
            l2,h2=box(e)
            if l2[0]-1<=hx<=h2[0]+1 and l2[1]-1<=hy<=h2[1]+1: mm=min(mm,hz-h2[2])
chk(mm>=460,'min head-to-service clearance %.1f >=460'%mm)
# PDU dedicated volume vs CHW
viol=[]
for p in pdus:
    lo,hi=box(p)
    for e in chw:
        l2,h2=box(e)
        if min(hi[0],h2[0])-max(lo[0],l2[0])>2 and min(hi[1],h2[1])-max(lo[1],l2[1])>2 and min(1959+1800,h2[2])-max(1959,l2[2])>2:
            viol.append((p.Name,e.Name))
chk(not viol,'no CHW in PDU 1800 dedicated space')

# supports: max gap along each busway
sup=[e for e in f.by_type('IfcBuildingElementProxy') if (e.ObjectType or '')=='Support']
worst=0
for e in svc['POWER']:
    lo,hi=box(e);d=hi-lo;k=int(np.argmax(d));pts=[]
    for q in sup:
        l2,h2=box(q);c=(l2+h2)/2
        if k==0:
            if abs(c[1]-(lo[1]+hi[1])/2)<10 and lo[0]-5<=c[0]<=hi[0]+5: pts.append(c[0])
        else:
            if abs(c[0]-(lo[0]+hi[0])/2)<10 and lo[1]-5<=c[1]<=hi[1]+5: pts.append(c[1])
    a,b=lo[k],hi[k];pts=sorted([a]+pts+[b]);gaps=[pts[i+1]-pts[i] for i in range(len(pts)-1)]
    worst=max(worst,max(gaps))
chk(worst<=1500,'busway max unsupported span %.0f <=1500'%worst)

# headroom: no overhead service below 2600
over=[e for es in svc.values() for e in es if box(e)[1][2]>0]
chk(not over,'no service above finished floor (headroom 3050)')


# ---- dimension / set-out checks against the requirement register ----
print('\nDIMENSION/SET-OUT CHECKS')
# room floor slab bbox
slabs=[e for e in f.by_type('IfcSlab') if (e.ObjectType or '')=='AccessFloor']
chk(len(slabs)==1,'one access-floor slab')
if slabs:
    lo,hi=box(slabs[0]); chk(abs(lo[0])<1 and abs(lo[1])<1 and abs(hi[0]-27000)<1 and abs(hi[1]-24000)<1,'floor bbox 27000 x 24000')
    chk(abs(hi[2])<1 and abs(hi[2]-lo[2]-35)<1,'floor top 0, thickness 35')
# columns on 7050/14250/21450
cx=sorted({round((box(e)[0][0]+box(e)[1][0])/2) for e in cols}); cy=sorted({round((box(e)[0][1]+box(e)[1][1])/2) for e in cols})
chk(cx==[7050,14250,21450],'column x grid %s'%cx); chk(cy==[7050,14250,21450],'column y grid %s'%cy)
# rack type dimensions
for typ,w,d in [('C1',600,1200),('C2',600,1070),('N1',800,1200),('N2',800,1070)]:
    es=[e for e in racks if pv(e,'Type')==typ]
    ok=len(es)>0 and all(abs(pv(e,'Width_mm')-w)<1e-6 and abs(pv(e,'Depth_mm')-d)<1e-6 and abs(pv(e,'Height_mm')-2000)<1e-6 for e in es)
    chk(ok,'rack %s %dx%d h2000 (%d)'%(typ,w,d,len(es)))
# CRAH dimensions
for e in crahs:
    lo,hi=box(e); w=hi[0]-lo[0]; d=hi[1]-lo[1]; h=hi[2]-lo[2]
    row=pv(e,'Row')
    if row=='PERIMETER': chk(abs(w-1200)<1 and abs(d-900)<1 and abs(h-2000)<1,'perimeter CRAH %s 1200x900x2000'%e.Name)
    else: chk(abs(w-600)<1 and abs(h-2000)<1 and abs(d-(1200 if row in 'AC' else 1070))<1,'in-row CRAH %s 600x%sx2000'%(e.Name,1200 if row in 'AC' else 1070))
# PDU dimensions
for e in pdus:
    lo,hi=box(e); chk(abs((hi[0]-lo[0])-762)<1 and abs((hi[1]-lo[1])-813)<1 and abs((hi[2]-lo[2])-1959)<1,'PDU %s 762x813x1959'%e.Name)
# containment roofs
roofs=[e for e in f.by_type('IfcCovering') if (e.ObjectType or '')=='ColdAisleRoof']
chk(len(roofs)>=2,'containment roofs present (%d)'%len(roofs))
for e in roofs:
    lo,hi=box(e); chk(abs((hi[2]-lo[2])-55.5)<1 and abs(lo[2]-2310)<1,'roof %s +2310..2365.5'%e.Name)
# service sections
for k,es in svc.items():
    lo,hi=box(es[0])
    if k=='TELECOM': chk(abs((hi[0]-lo[0])-683)<1 or abs((hi[1]-lo[1])-683)<1,'tray width 683')
    if k=='POWER': chk(abs((hi[0]-lo[0])-128)<1 or abs((hi[1]-lo[1])-128)<1,'busway width 128')
    if k.startswith('CHW'): chk(abs((hi[0]-lo[0])-168.3)<1 or abs((hi[1]-lo[1])-168.3)<1,'CHW envelope 168.3')
# head grid spacing (ceiling)
xs=sorted({round((box(e)[0][0]+box(e)[1][0])/2) for e in ceil})
chk(all(abs((xs[i+1]-xs[i])-2500)<1 for i in range(len(xs)-1)),'ceiling head x spacing 2500')
print('\nFAILURES TOTAL',len(fails))
sys.exit(1 if fails else 0)

